import ast,subprocess
def load(src):
    t=ast.parse(src); out={}
    for n in t.body:
        if isinstance(n,ast.ClassDef):
            out[n.name]=[b.target.id for b in n.body if isinstance(b,ast.AnnAssign)]
        elif isinstance(n,ast.FunctionDef):
            out[n.name+'()']=[a.arg for a in n.args.args+n.args.kwonlyargs]
    return out
ours=load(open('agent/calc.py').read())
theirs=load(subprocess.run(['git','show','origin/research/agent-architecture:agent/calc.py'],capture_output=True,text=True).stdout)
for k in sorted(set(ours)|set(theirs)):
    a,b=ours.get(k),theirs.get(k)
    if a!=b: print(k,'\n   ours  :',a,'\n   theirs:',b)
EOF
